Tool response:
Tool: schedule_test_drive
Description: Schedule Test Drive
Parameters:
    {
      "type": "object",
      "properties": {
        "lead_id": {
          "type": "integer",
          "title": "Lead Id"
        },
        "vehicle_id": {
          "type": "integer",
          "title": "Vehicle Id"
        },
        "salesperson_id": {
          "type": "integer",
          "title": "Salesperson Id"
        },
        "scheduled_at": {
          "type": "string",
          "title": "Scheduled At"
        },
        "duration_minutes": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Duration Minutes",
          "default": 30
        }
      },
      "required": [
        "lead_id",
        "vehicle_id",
        "salesperson_id",
        "scheduled_at"
      ]
    }

